var maximalRectangle = function(matrix) {
    if (!matrix || !matrix.length || !matrix[0].length) return 0;
    const cols = matrix[0].length;
    const heights = new Array(cols).fill(0);
    let answer = 0;
    for (const row of matrix) {
        for (let col = 0; col < cols; col++) {
            heights[col] = row[col] === '1' ? heights[col] + 1 : 0;
        }
        const stack = [];
        const extended = heights.concat([0]);
        for (let index = 0; index < extended.length; index++) {
            const height = extended[index];
            let start = index;
            while (stack.length && stack[stack.length - 1][1] > height) {
                const [popStart, oldHeight] = stack.pop();
                start = popStart;
                answer = Math.max(answer, oldHeight * (index - popStart));
            }
            stack.push([start, height]);
        }
    }
    return answer;
};

